from PIL import Image, ImageDraw
im = Image.open('/app/sharp.png').convert('RGB')
w,h=im.size
def crop(name,box,scale=3.0):
    c=im.crop(box).resize((int((box[2]-box[0])*scale),int((box[3]-box[1])*scale)), Image.LANCZOS)
    d=ImageDraw.Draw(c)
    for k in range(0,41):
        x=k*0.025*w
        if box[0]<=x<=box[2]:
            px=(x-box[0])*scale
            d.line([(px,0),(px,c.height)],fill=(255,0,0),width=1)
            if k%2==0: d.text((px+2,2),f'{k*2.5:.0f}',fill=(255,0,0))
    for k in range(0,41):
        y=k*0.025*h
        if box[1]<=y<=box[3]:
            py=(y-box[1])*scale
            d.line([(0,py),(c.width,py)],fill=(0,80,255),width=1)
            if k%2==0: d.text((2,py+2),f'{k*2.5:.0f}',fill=(0,80,255))
    c.save(f'/app/{name}.png'); print(name,c.size)
crop('mR1',(600,480,1150,780))   # patient right maxilla molar/premolar
crop('mL1',(1400,480,1950,780))  # patient left maxilla
"", "description": "High-res sharpened maxillary crops"}

